export const DEFAULT_EXERCISES: Exercise[] = seed.map((e) => ({ ...e, isCustom: false }));

/**
 * Stored exercise list + any built-ins it lacks. Accounts created before the
 * library grew get the new exercises; the user's own records (including edits)
 * stay as they are. Built-ins cannot be deleted, so nothing is resurrected.
 */
export function withBuiltInExercises(list: Exercise[] | null | undefined): Exercise[] {
  if (!list?.length) return DEFAULT_EXERCISES;
  const have = new Set(list.map((e) => e.id));
  const missing = DEFAULT_EXERCISES.filter((e) => !have.has(e.id));
  return missing.length ? [...list, ...missing] : list;
}
